<?php get_header();$w=xdj_words(); ?>
<main id="main" class="section product-detail"><?php while(have_posts()):the_post();$id=get_the_ID();$category=get_post_meta($id,'_xdj_category',true);$gallery=get_post_meta($id,'_xdj_gallery',true); ?>
<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url(xdj_page_url('services')); ?>"><?php echo esc_html($w[1]); ?></a><span>/</span><a href="<?php echo esc_url(xdj_category_url($category)); ?>"><?php echo esc_html(xdj_t($category)); ?></a><span>/</span><span><?php the_title(); ?></span></nav>
<div class="product-overview"><?php echo xdj_render_gallery($gallery?:[],get_the_title()); ?><div class="product-summary"><div class="eyebrow"><?php echo esc_html(xdj_t($category)); ?></div><h1><?php the_title(); ?></h1><p><?php echo esc_html(get_post_meta($id,'_xdj_description',true)); ?></p><a class="button" href="#product-enquiry"><?php echo esc_html(xdj_t('enquire')); ?> ↗</a><p><a href="tel:+441416286277">+44 (0)141 628 6277</a><br><a href="mailto:476638865z@gmail.com">476638865z@gmail.com</a></p><?php echo xdj_source_notice(); ?></div></div>
<article class="technical-content"><p class="source-note"><?php echo esc_html(xdj_t('image_note')); ?></p><?php the_content(); ?></article>
<nav class="product-pagination"><?php $position=(int)get_post_meta($id,'_xdj_position',true);foreach([-1=>'previous',1=>'next'] as $offset=>$label){$near=get_posts(['post_type'=>'product','lang'=>xdj_lang(),'numberposts'=>1,'meta_key'=>'_xdj_position','meta_value'=>$position+$offset]);if($near)echo '<a href="'.esc_url(get_permalink($near[0]->ID)).'">'.esc_html(xdj_t($label)).' · '.esc_html($near[0]->post_title).'</a>';} ?></nav>
<section id="product-enquiry"><h2><?php echo esc_html(xdj_t('enquire')); ?></h2><?php echo do_shortcode('[xdj_inquiry_form]'); ?></section>
<section><h2><?php echo esc_html(xdj_t('related')); ?></h2><?php $related=new WP_Query(['post_type'=>'product','lang'=>xdj_lang(),'posts_per_page'=>3,'post__not_in'=>[$id],'meta_query'=>[['key'=>'_xdj_category','value'=>$category],['key'=>'_xdj_alias_of','compare'=>'NOT EXISTS']]]);?><div class="catalogue"><?php while($related->have_posts()):$related->the_post();?><a class="service-card" href="<?php the_permalink(); ?>"><?php the_post_thumbnail('medium',['loading'=>'lazy','alt'=>get_the_title()]);?><h3><?php the_title(); ?></h3></a><?php endwhile;wp_reset_postdata();?></div></section>
<a class="text-link" href="<?php echo esc_url(xdj_content_url('cases')); ?>"><?php echo esc_html(xdj_t('cases')); ?> ↗</a>
<?php endwhile;?></main><?php get_footer(); ?>
